def get(self, key, default=None):
        p = self._path(key)
        if not os.path.exists(p):
            return default
        with open(p) as f:
            rec = json.load(f)
        if self._now() - rec["t"] > self.ttl:
            os.remove(p)
            return default
        return rec["v"]

    def cleanup(self):
        """Remove all expired entries from the cache directory."""
        now = self._now()
        for fname in os.listdir(self.root):
            if not fname.endswith(".json"):
                continue
            p = os.path.join(self.root, fname)
            try:
                with open(p) as f:
                    rec = json.load(f)
                if now - rec["t"] > self.ttl:
                    os.remove(p)
            except (OSError, json.JSONDecodeError):
                pass
